    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger residuals (wasted space)
    // We favor post_residual being as close to 0 as possible.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Penalty:
    // If post_residual is small but not zero, it is often "dead space" that cannot fit future items.
    // We penalize residuals that are smaller than the smallest likely item (e.g., 10),
    // unless the residual is exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead synergy:
    // If next_item_size is known, favor bins where post_residual can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        } else {
            // If we can't fit the next item, penalize proportionally to the wasted potential
            score += (next_item_size as f64) * 0.5;
        }
    }

    // 4. New Bin Thresholding:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only open a new bin if the current open bins are all "bad" (i.e., would result in high post_residuals).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to encourage filling existing ones
        score = 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // If it's a tight fit (fitting_bins_count is low), prioritize using this bin
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // 5. Global state calibration:
    // As the stream progresses, become more aggressive in minimizing open_bins_count
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (open_bins_count as f64);

