pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // We penalize larger post_residuals to favor tight packing.
    let mut score = post_res;

    // Interaction 1: Lookahead penalty. 
    // If the next item is large and won't fit in the remaining space of this bin,
    // penalize the current placement to encourage saving space for the next item.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size as f64 - post_res).powf(1.5);
    }

    // Interaction 2: Global packing efficiency.
    // As the stream progresses, prioritize closing bins (lower open_bins_count)
    // by penalizing empty space that deviates significantly from the global mean.
    let dev = (post_res - mean_residual).abs();
    score += dev * (1.0 + progress);

    // Interaction 3: New bin thresholding.
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to open a new bin if the current fit is extremely inefficient.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins early in the stream.
        // As the stream nears the end, lower the barrier to open new bins to ensure all items fit.
        score = 15.0 + (50.0 * (1.0 - progress));
    } else {
        // If this is the only bin that fits the item, reward it to prevent premature new bin creation.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Non-linear penalty for creating "dead space" (remnants < 10 are often unusable).
        if post_residual < 10 && post_residual > 0 {
            score += 10.0 / (post_res + 0.1);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
