    // If the post_residual is small but > 0, it's often better to have it larger.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Aggressive 2-step lookahead: 
    // If next_item_size fits perfectly into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
