    // If we have many open bins, we prefer to fill existing ones even if the fit is suboptimal.
    // If fitting_bins_count is 1, this is a critical bin; reduce penalty for poor fits.
    if fitting_bins_count > 1 {
        score += (open_bins_count as f64) * 2.0;
    } else {
        score -= 20.0;
    }

    // 4. Global balance:
    // Prefer bins that stay closer to the mean_residual to keep the distribution uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
