    // We favor larger post_residuals if they are above a threshold, or very small residuals (perfect fit).
    // The penalty is non-linear to discourage "sliver" gaps.
    let sliver_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post).powf(1.5) * 2.0
    } else {
        0.0
    };
    score += sliver_penalty;

    // Lookahead coupling: If a next item exists, penalize bins that leave a post_residual 
    // that is just slightly too small for the next item.
    if next_item_size > 0 {
        if post > 0.0 && post < next_item_size as f64 {
            score += (next_item_size as f64 - post).powf(1.2) * 1.5;
        }
    }

    // Progress coupling: As the stream nears completion, become more aggressive 
    // about filling existing bins to minimize total open bins.
    let density_pressure = (open_bins_count as f64 / 10.0) * progress;
    score += density_pressure * (post / bin_capacity as f64);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // proportional to the current progress and the number of fitting bins available.
    // This forces the heuristic to exhaust existing fitting bins before opening new ones.
    if bin_residual == bin_capacity {
        score += 40.0 + (fitting_bins_count as f64 * 10.0) + (progress * 20.0);
    }

    score
