    }

    // 3. New Bin Thresholding: If we are considering opening a new bin (bin_residual == bin_capacity),
    // we apply a steep penalty based on the number of open bins and mean residual.
    // Only open a new bin if the current options are very poor (high post_residual).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to force utilization of existing space.
        score += 45.0; 

        // If we have many bins open with large residuals, opening another is inefficient.
        score += mean_residual * 0.8;

        // If we have very few bins, opening a new one is less penalized.
        score -= (open_bins_count as f64) * 2.0;
    } else {
        // 4. Fragment Avoidance: If post_residual is small (e.g., < 10) but not 0, 
        // it creates "dead space" that is hard to fill. Penalize these fragments.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // 5. Last Chance Heuristic: If this is the only bin that can fit the item,
        // prioritize it over opening a new bin by lowering its score.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 6. Progression adjustment: As the stream nears completion, become more aggressive
    // about packing tightly to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
