        score -= 25.0 * (1.0 / (1.0 + diff));
    }

    // 3. Dynamic Thresholding: As the stream progresses, be more conservative about opening new bins.
    if bin_residual == bin_capacity {
        // New bin penalty increases as we approach the end of the stream.
        score += 20.0 + (progress * 40.0);

        // If we are early in the stream, favor opening bins to keep residuals high.
        if progress < 0.2 {
            score -= 15.0;
        }
    } else {
        // 4. Global state pressure: If we have many open bins, prioritize filling the tightest one.
        // Penalty for leaving a bin with large residual when many bins are open.
        score += (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // 5. If this is the last chance to fit the item in existing bins, reward it heavily to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
